CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, caption TEXT NOT NULL, author TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('pending','approved','hidden','rejected','deleted')), revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, synthetic INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (id TEXT PRIMARY KEY,n INTEGER NOT NULL,expires INTEGER NOT NULL);
